            <TextField
                {...textFieldProps}
                helperText={helperText}
                id={fieldId}
                slotProps={{
                    formHelperText: { id: helperTextId },
                    ...inputSlotProps,
                }}
                sx={{ minWidth: 0 }}
            />
        </Stack>
    )
}

