    actionService.draftStore.getDraft(definition.id)
    actionService.draftStore.stageDraft(definition.id, definition)
    render(
        <AppThemeProvider>
            <ActionDefinitionFields
                actionId={definition.id}
                actions={[
                    { id: 'before', label: 'Before' },
                    { id: 'after', label: 'After' },
