                cardTypes={['feature']}
                sourcePath={SOURCE_PATH}
                specialContextTypes={['actions']}
                states={['ready']}
                worktrees={[]}
            />
        </AppThemeProvider>,
    )

    return () => actionService.draftStore.getDraft(definition.id).definition
}

